/// Handles `[section]` headers, bare `key = "value"` pairs, comments, and
/// blank lines. Keys under a section are stored as `section.key`. Quoted
/// string values have their quotes stripped; unquoted values are stored
/// as-is.
pub fn toml_parse(content: &str) -> HashMap<String, String> {
    let mut map = HashMap::new();
    let mut section = String::new();

    for line in content.lines() {
        let trimmed = line.trim();

        // Skip blank lines and comments
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        // Section header: [name]
        if let Some(inner) = trimmed.strip_prefix('[').and_then(|s| s.strip_suffix(']')) {
            section = inner.trim().to_string();
            continue;
        }

        // Key = value
        if let Some((key, value)) = trimmed.split_once('=') {
            let key = key.trim();
            let value = value.trim();

            // Strip surrounding quotes from string values
            let value = if (value.starts_with('"') && value.ends_with('"'))
                || (value.starts_with('\'') && value.ends_with('\''))
            {
                &value[1..value.len() - 1]
            } else {
                value
            };

            let full_key = if section.is_empty() {
                key.to_string()
            } else {
                format!("{section}.{key}")
            };

            map.insert(full_key, value.to_string());
        }
    }

    map
}

/// Look up a `.`-joined config key (e.g. `"repos.work"`) in a loaded config map.
        Some(idx) => (&path[..idx], &path[idx + 1..]),
        None => ("", path),
    }
}

/// Format a raw value string per `kind`, the way a default or an
/// example is rendered on the assignment line: `Usize` bare,
/// `Str`/`ItemList` quoted.
fn format_value(kind: ValueKind, raw: &str) -> String {
    match kind {
        ValueKind::Usize => raw.to_string(),
        ValueKind::Str | ValueKind::ItemList => format!("{raw:?}"),
    }
}

/// Render a key's value cell: the quoted/bare default, or an
/// angle-bracket placeholder by kind when there is no default,
/// except a required key with no default, which renders
/// `<required>` so it stands out.
pub fn render_value(key: &ConfigKey) -> String {
    match key.default {
        Some(d) => format_value(key.kind, d),
        None => {
            if key.required {
                "<required>".to_string()
            } else {
                match key.kind {
                    ValueKind::Str => "<str>".to_string(),
                    ValueKind::Usize => "<usize>".to_string(),
                    ValueKind::ItemList => "<items>".to_string(),
                }
            }
        }
    }
}

